using System.Text;
using System.Text.Json;
using System.Text.Json.Nodes;
using GenesisMesh;
using NSec.Cryptography;
using Xunit;

namespace GenesisMesh.Sdk.Tests;

/// <summary>
/// Shared conformance suite <c>field_registry</c> (v1.2.0), generated by the Python reference
/// (genesismesh/conformance/generate_vectors.py field_registry) and copied here unchanged: the field
/// registry of signed records and the fields every verifier refuses.
/// </summary>
public class FieldRegistryConformanceTests
{
    private static readonly string SuitePath = Path.Combine(AppContext.BaseDirectory, "testdata", "conformance", "field_registry.json");
    private static readonly string InteropPath = Path.Combine(AppContext.BaseDirectory, "testdata", "conformance", "interop.json");
    private static readonly HashSet<string> KindsRun = new() { "unknown_fields", "verify_decision", "verify_agreement", "export" };

    /// <summary>
    /// Entry kinds: the vectors expect every kind of the registry to be verified, and this SDK verifies the kinds a
    /// governed store holds (1.9.0, <see cref="OfflineVerifier.VerifiedEntryKinds"/>).
    /// </summary>
    private static readonly HashSet<string> KindsNotRun = new() { "entry_kind" };

    private static JsonElement Suite() => JsonDocument.Parse(File.ReadAllText(SuitePath)).RootElement;

    private static JsonElement Vector(string id) =>
        Suite().GetProperty("vectors").EnumerateArray().Single(x => x.GetProperty("id").GetString() == id);

    public static IEnumerable<object[]> VectorIds() => Suite().GetProperty("vectors").EnumerateArray()
        .Where(v => !KindsNotRun.Contains(v.GetProperty("kind").GetString()!))
        .Select(v => new object[] { v.GetProperty("id").GetString()! });

    internal static ConformanceReceipt Receipt() => ConformanceReceipts.For(
        "field_registry", typeof(FieldRegistryConformanceTests), nameof(ReproducesTheReferenceOutcome), VectorIds(),
        KindsRun, KindsNotRun);

    [Fact]
    public void EveryKindIsRunOrListedAsNotRun() => ConformanceReceipts.Record(Receipt());

    [Fact]
    public void EmbedsTheRegistryOfTheSuite()
    {
        var suite = JsonNode.Parse(Suite().GetProperty("registry").GetRawText());
        var embedded = JsonNode.Parse(StrictFields.RegistryJson);
        Assert.True(JsonNode.DeepEquals(suite, embedded),
            "canonical_registry.json differs from the suite: run `python scripts/sync_canonical_registry.py`");
    }

    [Fact]
    public void KeepsThisSdksCanonicalRulesEqualToTheRegistrys()
    {
        Assert.Equal(OfflineVerifier.DecisionOmittedWhenAbsent, StrictFields.Model("BoundaryDecision").OmitWhenNone);
        Assert.Equal(OfflineVerifier.AgreementCanonicalKeys, StrictFields.Model("AgreementRecord").CanonicalFields);
        Assert.Equal(OfflineVerifier.PolicyOmittedWhenAbsent, StrictFields.Model("BoundaryPolicy").OmitWhenNone);
    }

    /// <summary>
    /// The reference's BoundaryPolicy.digest() of the field registry's <c>boundarypolicy-guided</c> record
    /// (v1.4.0); without the new sections it is the digest bd-001 binds.
    /// </summary>
    private const string GuidedPolicyDigest = "768bdcfaadfbd0bd434a86990c6567c23bee8978aafa75a5ed88ef2d2e54cb95";
    private const string BoundPolicyDigest = "7921f8ac5dccd5cfb09489e69ca1d0325158e7b457de65a7fc4563af7f7b8601";

    [Fact]
    public void APolicyWithoutTheStage3SectionsKeepsItsDigest()
    {
        // v1.4.0: remediation, review_required and emergency are left out when absent, so null reads as
        // absent and a 1.3 policy keeps its digest.
        var bd = Input("bd-001");
        var policy = bd.GetProperty("expected_policies")[0];
        Assert.Equal(BoundPolicyDigest, OfflineVerifier.PolicyDigest(policy.GetRawText()));
        var nulls = WithValue(policy, "remediation", "null");
        nulls["review_required"] = null;
        nulls["emergency"] = null;
        Assert.Equal(BoundPolicyDigest, OfflineVerifier.PolicyDigest(nulls.ToJsonString()));
        var r = OfflineVerifier.VerifyBoundaryDecision(bd.GetProperty("decision").GetRawText(), new DecisionVerifyOptions
        {
            OperatorPublicKeys = Strings(bd, "operator_public_keys"),
            Now = OfflineVerifier.ParseTimestamp(bd.GetProperty("now").GetString()!),
            ExpectedPolicies = new[] { nulls.ToJsonString() },
        });
        Assert.Equal((true, "authorized"), (r.Accepted, r.Reason));
        Assert.Equal(GuidedPolicyDigest,
            OfflineVerifier.PolicyDigest(Vector("boundarypolicy-guided").GetProperty("record").GetRawText()));
    }

    [Fact]
    public void ADecisionUnderAPolicyWithTheStage3SectionsVerifiesOffline()
    {
        // v1.4.0: a policy with remediation guidance, a review requirement and an emergency section is
        // known to this SDK, and binds by its digest.
        var bd = Input("bd-001");
        var guided = Vector("boundarypolicy-guided").GetProperty("record");
        var decision = JsonNode.Parse(bd.GetProperty("decision").GetRawText())!.AsObject();
        var binding = decision["policy_binding"]!.AsObject();
        var applied = binding["policies"]![0]!.AsObject();
        applied["policy_digest"] = GuidedPolicyDigest;
        binding["policy_set_digest"] = OfflineVerifier.PolicySetDigest(new[]
        {
            (applied["policy_id"]!.GetValue<string>(), applied["version"]!.ToJsonString(), GuidedPolicyDigest),
        });
        using var key = ConformanceKey(Strings(bd, "operator_public_keys"));
        var signed = Resigned(decision, key);
        DecisionVerificationResult Verify(string policy) => OfflineVerifier.VerifyBoundaryDecision(signed, new DecisionVerifyOptions
        {
            OperatorPublicKeys = Strings(bd, "operator_public_keys"),
            Now = OfflineVerifier.ParseTimestamp(bd.GetProperty("now").GetString()!),
            ExpectedPolicies = new[] { policy },
        });
        var ok = Verify(guided.GetRawText());
        Assert.Equal((true, "authorized"), (ok.Accepted, ok.Reason));
        // The sections are signed: the policy without them binds another digest.
        Assert.Equal("policy_binding_mismatch", Verify(bd.GetProperty("expected_policies")[0].GetRawText()).Reason);
        Assert.Equal("unknown_field", Verify(WithField(guided, "x_added_field")).Reason);
    }

    [Fact]
    public void HasEnoughVectors() => Assert.True(Suite().GetProperty("vectors").GetArrayLength() >= 70);

    [Theory]
    [MemberData(nameof(VectorIds))]
    public void ReproducesTheReferenceOutcome(string id)
    {
        var v = Vector(id);
        var expected = v.GetProperty("expected");
        switch (v.GetProperty("kind").GetString())
        {
            case "unknown_fields":
                var want = expected.GetProperty("unknown_fields").EnumerateArray().Select(e => e.GetString()!).ToList();
                Assert.Equal(want, StrictFields.UnknownFields(v.GetProperty("model").GetString()!, v.GetProperty("record")));
                break;
            case "verify_decision":
                {
                    var input = v.GetProperty("input");
                    var r = OfflineVerifier.VerifyBoundaryDecision(input.GetProperty("decision").GetRawText(), new DecisionVerifyOptions
                    {
                        OperatorPublicKeys = Strings(input, "operator_public_keys"),
                        Now = OfflineVerifier.ParseTimestamp(input.GetProperty("now").GetString()!),
                    });
                    Assert.Equal((expected.GetProperty("accepted").GetBoolean(), expected.GetProperty("reason").GetString()), (r.Accepted, r.Reason));
                    break;
                }
            case "verify_agreement":
                {
                    var input = v.GetProperty("input");
                    var r = OfflineVerifier.VerifyAgreement(input.GetProperty("agreement").GetRawText(),
                        Strings(input, "offerer_public_keys"), Strings(input, "responder_public_keys"));
                    Assert.Equal((expected.GetProperty("accepted").GetBoolean(), expected.GetProperty("reason").GetString()), (r.Accepted, r.Reason));
                    break;
                }
            case "export":
                {
                    // 1.9.0: an export verified offline, without executor keys.
                    var input = v.GetProperty("input");
                    var r = OfflineVerifier.VerifyEvidenceEvents(OfflineVerifier.ParseExportLines(input.GetProperty("lines").GetString()!),
                        new EvidenceVerifyOptions
                        {
                            NAPublicKeys = input.TryGetProperty("na_public_keys", out _) ? Strings(input, "na_public_keys") : [],
                        });
                    var failures = expected.GetProperty("failures").EnumerateArray()
                        .Select(f => (f.GetProperty("store_sequence").GetInt64(), f.GetProperty("reason").GetString())).ToList();
                    Assert.Equal(failures, r.Failures.Select(f => (f.StoreSequence!.Value, (string?)f.Reason)));
                    break;
                }
            default:
                throw new InvalidOperationException($"vector kind {v.GetProperty("kind").GetString()} is not run");
        }
    }

    [Fact]
    public void AnEntryAfterAnUnknownKindStillChains()
    {
        // 1.9.0, as in TypeScript: the same line twice is an unknown kind, a gap, and an unknown kind again.
        var line = Vector("export-unknown-entry-kind").GetProperty("input").GetProperty("lines").GetString()!;
        var events = OfflineVerifier.ParseExportLines(line).Concat(OfflineVerifier.ParseExportLines(line));
        var r = OfflineVerifier.VerifyEvidenceEvents(events, new EvidenceVerifyOptions());
        Assert.Equal(["unknown_entry_kind", "store_sequence_gap", "unknown_entry_kind"], r.Failures.Select(f => f.Reason));
    }

    private static JsonElement Input(string id) =>
        JsonDocument.Parse(File.ReadAllText(InteropPath)).RootElement.GetProperty("vectors").EnumerateArray()
            .Single(v => v.GetProperty("id").GetString() == id).GetProperty("input");

    private static string WithField(JsonElement record, string key)
    {
        var node = JsonNode.Parse(record.GetRawText())!.AsObject();
        node[key] = "x";
        return node.ToJsonString();
    }

    private static List<string> Strings(JsonElement input, string key) =>
        input.GetProperty(key).EnumerateArray().Select(e => e.GetString()!).ToList();

    [Fact]
    public void AnExpectedPolicyWithAnUnknownFieldIsRefusedByName()
    {
        var newer = Vector("verify-decision-newer-signed-field").GetProperty("input");
        var r = OfflineVerifier.VerifyBoundaryDecision(newer.GetProperty("decision").GetRawText(), new DecisionVerifyOptions
        {
            OperatorPublicKeys = Strings(newer, "operator_public_keys"),
            Now = OfflineVerifier.ParseTimestamp(newer.GetProperty("now").GetString()!),
            ExpectedPolicies = new[] { Vector("boundarypolicy-top").GetProperty("record").GetRawText() },
        });
        Assert.Equal("unknown_field", r.Reason);
    }

    [Fact]
    public void AFieldOutsideTheSignatureFailsTheSignature()
    {
        var bd = Input("bd-003");
        var options = new DecisionVerifyOptions
        {
            OperatorPublicKeys = Strings(bd, "operator_public_keys"),
            Now = OfflineVerifier.ParseTimestamp(bd.GetProperty("now").GetString()!),
        };
        Assert.Equal("authorized", OfflineVerifier.VerifyBoundaryDecision(bd.GetProperty("decision").GetRawText(), options).Reason);
        var added = OfflineVerifier.VerifyBoundaryDecision(WithField(bd.GetProperty("decision"), "risk_tier"), options);
        Assert.False(added.Accepted);
        Assert.Equal("invalid_signature", added.Reason);

        var agr = Input("agr-001");
        Assert.True(OfflineVerifier.VerifyAgreement(WithField(agr.GetProperty("agreement"), "x"),
            Strings(agr, "offerer_public_keys"), Strings(agr, "responder_public_keys")).Accepted);

        var pol = Input("pol-001");
        Assert.False(OfflineVerifier.VerifyDataLicensePolicySignature(WithField(pol.GetProperty("policy"), "x"),
            Strings(pol, "licensor_public_keys")));

        var intent = Input("int-001");
        var at = OfflineVerifier.ParseTimestamp(intent.GetProperty("at").GetString()!);
        var unsigned = OfflineVerifier.VerifyDataAccessIntent(WithField(intent.GetProperty("intent"), "x"),
            intent.GetProperty("policy").GetRawText(), Strings(intent, "agent_public_keys"), at);
        Assert.False(unsigned.Valid);
        Assert.Equal("Invalid intent signature", Assert.Single(unsigned.Violations).Detail);
        var policy = OfflineVerifier.VerifyDataAccessIntent(intent.GetProperty("intent").GetRawText(),
            WithField(intent.GetProperty("policy"), "x"), Strings(intent, "agent_public_keys"), at);
        Assert.False(policy.Valid);
        Assert.Equal("Unknown field: policy.x", Assert.Single(policy.Violations).Detail);
    }

    private static DecisionVerifyOptions Options(JsonElement input) => new()
    {
        OperatorPublicKeys = Strings(input, "operator_public_keys"),
        Now = OfflineVerifier.ParseTimestamp(input.GetProperty("now").GetString()!),
    };

    private static JsonObject WithValue(JsonElement record, string key, string json)
    {
        var node = JsonNode.Parse(record.GetRawText())!.AsObject();
        node[key] = JsonNode.Parse(json);
        return node;
    }

    /// <summary>The vector generator's signing key (seeds 00..1f, 20..3f, 40..5f) for one of the public keys.</summary>
    private static Key ConformanceKey(IReadOnlyCollection<string> publicKeys)
    {
        foreach (var start in new[] { 0, 32, 64 })
        {
            var key = Key.Import(SignatureAlgorithm.Ed25519, Enumerable.Range(start, 32).Select(i => (byte)i).ToArray(),
                KeyBlobFormat.RawPrivateKey);
            if (publicKeys.Contains(Convert.ToBase64String(key.PublicKey.Export(KeyBlobFormat.RawPublicKey)))) return key;
            key.Dispose();
        }
        throw new InvalidOperationException("no generator key for these public keys");
    }

    /// <summary>The decision signed over its signed form, as the vector generator signs it.</summary>
    private static string Resigned(JsonObject decision, Key key)
    {
        using var doc = JsonDocument.Parse(decision.ToJsonString());
        var body = Canonical.Of(doc.RootElement, new[] { "signature" }, OfflineVerifier.DecisionOmittedWhenAbsent);
        decision["signature"] = new JsonObject
        {
            ["key_id"] = "k",
            ["sig"] = Convert.ToBase64String(SignatureAlgorithm.Ed25519.Sign(key, Encoding.UTF8.GetBytes(body))),
        };
        return decision.ToJsonString();
    }

    [Theory]
    [InlineData("{\"key_id\":\"k\",\"sig\":\"\"}")]
    [InlineData("{}")]
    [InlineData("\"abc\"")]
    [InlineData("[]")]
    [InlineData("5")]
    public void ASignatureOfAnotherShapeIsInvalidNotMissing(string signature)
    {
        // v1.3.1: missing only when absent or null, as in the reference.
        var bd = Input("bd-003");
        var decision = WithValue(bd.GetProperty("decision"), "signature", signature).ToJsonString();
        Assert.Equal("invalid_signature", OfflineVerifier.VerifyBoundaryDecision(decision, Options(bd)).Reason);

        var intent = Input("int-001");
        var r = OfflineVerifier.VerifyDataAccessIntent(WithValue(intent.GetProperty("intent"), "signature", signature).ToJsonString(),
            intent.GetProperty("policy").GetRawText(), Strings(intent, "agent_public_keys"),
            OfflineVerifier.ParseTimestamp(intent.GetProperty("at").GetString()!));
        Assert.Equal("Invalid intent signature", Assert.Single(r.Violations).Detail);
    }

    [Fact]
    public void ASignatureIsMissingOnlyWhenAbsentOrNull()
    {
        var bd = Input("bd-003");
        Assert.Equal("missing_signature", OfflineVerifier.VerifyBoundaryDecision(
            WithValue(bd.GetProperty("decision"), "signature", "null").ToJsonString(), Options(bd)).Reason);
        var absent = WithValue(bd.GetProperty("decision"), "signature", "null");
        absent.Remove("signature");
        Assert.Equal("missing_signature", OfflineVerifier.VerifyBoundaryDecision(absent.ToJsonString(), Options(bd)).Reason);
        var expired = Input("bd-006");
        Assert.Equal("decision_expired", OfflineVerifier.VerifyBoundaryDecision(
            WithValue(expired.GetProperty("decision"), "signature", "{\"sig\":\"\"}").ToJsonString(), Options(expired)).Reason);

        var intent = Input("int-001");
        var r = OfflineVerifier.VerifyDataAccessIntent(WithValue(intent.GetProperty("intent"), "signature", "null").ToJsonString(),
            intent.GetProperty("policy").GetRawText(), Strings(intent, "agent_public_keys"),
            OfflineVerifier.ParseTimestamp(intent.GetProperty("at").GetString()!));
        Assert.Equal("Missing intent signature", Assert.Single(r.Violations).Detail);
    }

    [Theory]
    [InlineData("\"x\"")]
    [InlineData("\"\"")]
    [InlineData("null")]
    [InlineData("true")]
    public void AnExpiryThatDoesNotParseIsLeftToTheSignatureAndFormChecks(string expiry)
    {
        // v1.3.1: as in the reference; it was a FormatException before any of them.
        var newer = Vector("verify-decision-newer-signed-field").GetProperty("input");
        using var key = ConformanceKey(Strings(newer, "operator_public_keys"));
        var decision = WithValue(newer.GetProperty("decision"), "decision_valid_until", expiry);
        Assert.Equal("invalid_signature", OfflineVerifier.VerifyBoundaryDecision(decision.ToJsonString(), Options(newer)).Reason);
        Assert.Equal("unknown_field", OfflineVerifier.VerifyBoundaryDecision(Resigned(decision, key), Options(newer)).Reason);
    }

    [Fact]
    public void AnExpiryThatDoesNotParseIsNeverAccepted()
    {
        var newer = Vector("verify-decision-newer-signed-field").GetProperty("input");
        using var key = ConformanceKey(Strings(newer, "operator_public_keys"));
        var decision = WithValue(Input("bd-003").GetProperty("decision"), "decision_valid_until", "5");
        Assert.Throws<FormatException>(() => OfflineVerifier.VerifyBoundaryDecision(Resigned(decision, key), Options(newer)));
    }

    [Theory]
    [InlineData("policy_id")]
    [InlineData("allowed_source_ids")]
    [InlineData("allowed_access_types")]
    [InlineData("max_volume_bytes_per_session")]
    [InlineData("prohibited_classification_tags")]
    public void AnIntentCheckRefusesAPolicyMissingAFieldTheReferenceWrites(string field)
    {
        // v1.3.0: the policy's whole canonical form is checked, not only its timestamps; the
        // reference matches this in 1.3.1.
        var intent = Input("int-001");
        var policy = JsonNode.Parse(intent.GetProperty("policy").GetRawText())!.AsObject();
        Assert.True(policy.Remove(field));
        var r = OfflineVerifier.VerifyDataAccessIntent(intent.GetProperty("intent").GetRawText(), policy.ToJsonString(),
            Strings(intent, "agent_public_keys"), OfflineVerifier.ParseTimestamp(intent.GetProperty("at").GetString()!));
        Assert.False(r.Valid);
        Assert.Equal("Not in canonical form: policy", Assert.Single(r.Violations).Detail);
    }
}
